import { createFirebaseClient, auth as firebaseAuth } from './firebase-client.js';

const supabase = createFirebaseClient();
const configured = true;

const state = { user: null, membership: null, organization: null, view: 'dashboard', period: 'month', offerings: [], tithes: [], brothers: [], currentData: [], channel: null };
const $ = (id) => document.getElementById(id);
const today = () => new Date().toISOString().slice(0, 10);
const money = (cents = 0) => new Intl.NumberFormat('pt-MZ', { style: 'currency', currency: state.organization?.currency || 'MZN', minimumFractionDigits: 2 }).format(Number(cents) / 100);
const dateText = (value) => value ? new Intl.DateTimeFormat('pt-MZ', { dateStyle: 'medium' }).format(new Date(`${value}T12:00:00`)) : '—';
const dateTimeText = (value) => value ? new Intl.DateTimeFormat('pt-MZ', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) : '—';
const esc = (value = '') => String(value).replace(/[&<>'"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[c]));
const initials = (name = '') => name.split(/\s+/).filter(Boolean).slice(0, 2).map(x => x[0]).join('').toUpperCase() || '—';
const roleLabel = (role) => ({ admin: 'Administrador', treasurer: 'Tesoureiro', viewer: 'Consulta' }[role] || role || 'Utilizador');
const isAdmin = () => state.membership?.role === 'admin';
const canWrite = () => ['admin', 'treasurer'].includes(state.membership?.role);

function toast(message, error = false) {
  const el = document.createElement('div'); el.className = `toast${error ? ' error' : ''}`; el.textContent = message; $('toast-region').appendChild(el);
  setTimeout(() => el.remove(), 4500);
}
function formMessage(id, message = '', error = false) { const el = $(id); if (!el) return; el.hidden = !message; el.textContent = message; el.className = `form-message${error ? ' error' : ' success'}`; }
function setBusy(button, busy, busyText = 'A guardar…') { if (!button) return; button.disabled = busy; if (busy) { button.dataset.original = button.textContent; button.textContent = busyText; } else if (button.dataset.original) button.textContent = button.dataset.original; }
function dateRange(period = state.period) {
  const end = new Date(); const start = new Date(end);
  if (period === 'today') start.setHours(0, 0, 0, 0);
  else if (period === 'week') { const day = (end.getDay() + 6) % 7; start.setDate(end.getDate() - day); }
  else if (period === 'year') start.setMonth(0, 1);
  else start.setDate(1);
  return { from: start.toISOString().slice(0, 10), to: end.toISOString().slice(0, 10) };
}
function showAuthMessage(message, error = true) { formMessage('auth-message', message, error); }
function setAuthMode(mode) {
  document.querySelectorAll('[data-auth-mode]').forEach(btn => { const active = btn.dataset.authMode === mode; btn.classList.toggle('active', active); btn.setAttribute('aria-selected', String(active)); });
  $('login-form').hidden = mode !== 'login'; $('register-form').hidden = mode !== 'register'; showAuthMessage('');
}
function openDialog(id) { const d = $(id); if (d && !d.open) d.showModal(); }
function closeDialog(id) { const d = $(id); if (d?.open) d.close(); }
function setView(view) {
  state.view = view; document.querySelectorAll('.nav-item[data-view]').forEach(btn => btn.classList.toggle('active', btn.dataset.view === view));
  const titles = { dashboard: 'Visão geral', offerings: 'Ofertas', tithes: 'Dízimos', brothers: 'Irmãos', day: 'Registros por dia', calendar: 'Calendário', closures: 'Fechos diários', reports: 'Relatórios', admin: 'Administração' }; $('page-title').textContent = titles[view] || 'Visão geral';
  $('sidebar').classList.remove('open'); $('mobile-overlay').hidden = true; renderView();
}
async function queryRows(table, queryBuilder) { let q = supabase.from(table).select('*').eq('organization_id', state.organization.id).is('deleted_at', null); if (queryBuilder) q = queryBuilder(q); const { data, error } = await q; if (error) throw error; return data || []; }
async function loadWorkspace() {
  if (!supabase || !state.user) return;
  const { data: member, error } = await supabase.from('organization_members').select('id, role, active, organization_id, organizations(*)').eq('user_id', state.user.id).eq('active', true).maybeSingle();
  if (error) throw error;
  if (!member) { openDialog('setup-dialog'); return; }
  state.membership = member; state.organization = member.organizations;
  $('user-name').textContent = state.user.user_metadata?.full_name || state.user.displayName || state.user.email?.split('@')[0] || 'Utilizador'; $('user-avatar').textContent = initials($('user-name').textContent); $('user-role').textContent = roleLabel(member.role); document.querySelectorAll('.admin-only').forEach(el => { el.hidden = !isAdmin(); });
  $('auth-view').hidden = true; $('app-view').hidden = false;
  subscribeRealtime(); await renderView();
}
function subscribeRealtime() {
  if (!supabase || !state.organization) return;
  if (state.channel) supabase.removeChannel(state.channel);
  state.channel = supabase.channel(`org-${state.organization.id}`).on('postgres_changes', { event: '*', schema: 'public', table: 'offerings', filter: `organization_id=eq.${state.organization.id}` }, () => renderView()).on('postgres_changes', { event: '*', schema: 'public', table: 'tithes', filter: `organization_id=eq.${state.organization.id}` }, () => renderView()).on('postgres_changes', { event: '*', schema: 'public', table: 'brothers', filter: `organization_id=eq.${state.organization.id}` }, () => renderView()).subscribe((status) => { $('sync-label').textContent = status === 'SUBSCRIBED' ? 'Ligado e sincronizado' : 'A sincronizar…'; });
}
async function fetchFinancial(from, to) {
  const [o, t] = await Promise.all([queryRows('offerings', q => q.gte('business_date', from).lte('business_date', to).order('business_date', { ascending: false }).order('created_at', { ascending: false })), queryRows('tithes', q => q.gte('delivery_date', from).lte('delivery_date', to).order('delivery_date', { ascending: false }).order('created_at', { ascending: false }))]);
  state.offerings = o; state.tithes = t; return { offerings: o, tithes: t };
}
async function fetchBrothers() { state.brothers = await queryRows('brothers', q => q.order('full_name', { ascending: true })); return state.brothers; }
function total(rows) { return rows.reduce((sum, row) => sum + Number(row.amount_cents || 0), 0); }
function periodLabel() { return ({ today: 'Hoje', week: 'Esta semana', month: 'Este mês', year: 'Este ano' }[state.period] || 'Período'); }
function pageHeading(title, subtitle, action = '') { return `<div class="page-heading"><div><p class="eyebrow">Alfa e Ómega · Sector ${esc(state.organization?.sector || '8')}</p><h2>${title}</h2><p>${subtitle}</p></div>${action}</div>`; }
function loading() { $('page-content').innerHTML = '<div class="empty-state"><strong>A carregar dados seguros…</strong><span>Estamos a atualizar a sua sessão.</span></div>'; }
async function renderView() {
  if (!state.organization) return; loading();
  try { if (state.view === 'dashboard') await renderDashboard(); else if (state.view === 'offerings') await renderOfferings(); else if (state.view === 'tithes') await renderTithes(); else if (state.view === 'brothers') await renderBrothers(); else if (state.view === 'day') await renderDay(); else if (state.view === 'calendar') await renderCalendar(); else if (state.view === 'closures') await renderClosures(); else if (state.view === 'reports') await renderReports(); else if (state.view === 'admin' && isAdmin()) await renderAdmin(); else if (state.view === 'admin') setView('dashboard'); } catch (error) { console.error(error); $('page-content').innerHTML = `<div class="panel"><div class="form-message error">Não foi possível carregar os dados. Tente atualizar a página.</div></div>`; }
}
function periodSelect() { return `<select id="period-select" class="select-control" aria-label="Período"><option value="today" ${state.period === 'today' ? 'selected' : ''}>Hoje</option><option value="week" ${state.period === 'week' ? 'selected' : ''}>Esta semana</option><option value="month" ${state.period === 'month' ? 'selected' : ''}>Este mês</option><option value="year" ${state.period === 'year' ? 'selected' : ''}>Este ano</option></select>`; }
async function renderDashboard() {
  const range = dateRange(); const { offerings, tithes } = await fetchFinancial(range.from, range.to); const all = [...offerings.map(x => ({ ...x, kind: 'Oferta', date: x.business_date })), ...tithes.map(x => ({ ...x, kind: 'Dízimo', date: x.delivery_date }))].sort((a, b) => `${b.date}${b.created_at}`.localeCompare(`${a.date}${a.created_at}`));
  const daily = {}; all.forEach(row => { daily[row.date] ||= { offering: 0, tithe: 0 }; daily[row.date][row.kind === 'Oferta' ? 'offering' : 'tithe'] += Number(row.amount_cents); });
  const days = Object.keys(daily).sort().slice(-7); const max = Math.max(1, ...days.flatMap(d => [daily[d].offering, daily[d].tithe]));
  const bars = days.length ? days.map(d => `<div class="chart-column"><div class="bar-stack"><span class="bar offering" style="height:${Math.max(2, daily[d].offering / max * 100)}%" title="Ofertas: ${money(daily[d].offering)}"></span><span class="bar tithe" style="height:${Math.max(2, daily[d].tithe / max * 100)}%" title="Dízimos: ${money(daily[d].tithe)}"></span></div><span class="chart-label">${new Date(`${d}T12:00:00`).toLocaleDateString('pt-MZ', { day: '2-digit', month: 'short' }).replace('.', '')}</span></div>`).join('') : '<div class="empty-state">Ainda não há movimentos neste período.</div>';
  $('page-content').innerHTML = `${pageHeading('Visão geral', `Resumo financeiro de ${periodLabel().toLowerCase()}.`, periodSelect())}<section class="summary-grid"><article class="summary-card"><span class="summary-label">Ofertas</span><strong class="summary-value">${money(total(offerings))}</strong><span class="summary-meta">${offerings.length} lançamento(s)</span></article><article class="summary-card"><span class="summary-label">Dízimos</span><strong class="summary-value">${money(total(tithes))}</strong><span class="summary-meta">${tithes.length} lançamento(s)</span></article><article class="summary-card"><span class="summary-label">Total arrecadado</span><strong class="summary-value">${money(total(offerings) + total(tithes))}</strong><span class="summary-meta">Dados sincronizados</span></article><article class="summary-card"><span class="summary-label">Último movimento</span><strong class="summary-value">${all[0] ? dateText(all[0].date) : '—'}</strong><span class="summary-meta">${all[0] ? esc(all[0].kind) : 'Nenhum registo'}</span></article></section><div class="two-col"><section class="panel"><div class="panel-head"><h3>Evolução financeira</h3><span>Últimos dias com movimentos</span></div><div class="chart-box">${bars}</div><div class="legend"><span><i class="green"></i> Ofertas</span><span><i class="gold"></i> Dízimos</span></div></section><section class="panel"><div class="panel-head"><h3>Movimentos recentes</h3><button class="action-link" data-view="day">Ver por dia</button></div>${all.length ? `<ul class="activity-list">${all.slice(0, 6).map(row => `<li><div class="activity-main"><strong>${esc(row.kind === 'Oferta' ? row.offering_type : (row.brother_name || 'Dízimo'))}</strong><span>${dateText(row.date)} · ${esc(row.reference || 'Sem referência')}</span></div><span class="activity-value">${money(row.amount_cents)}</span></li>`).join('')}</ul>` : '<div class="empty-state"><strong>Sem movimentos</strong><span>Os lançamentos aparecerão aqui.</span></div>'}</section></div>`;
  $('period-select')?.addEventListener('change', async e => { state.period = e.target.value; await renderDashboard(); }); document.querySelector('[data-view="day"]')?.addEventListener('click', () => setView('day'));
}
function entryButton(type) { return canWrite() ? `<button class="button primary" data-new-entry="${type}">+ Registar ${type === 'offering' ? 'oferta' : 'dízimo'}</button>` : ''; }
async function renderOfferings() { const range = { from: '2000-01-01', to: '2999-12-31' }; const { offerings } = await fetchFinancial(range.from, range.to); $('page-content').innerHTML = `${pageHeading('Ofertas', 'Registos de ofertas e arrecadações da igreja.', entryButton('offering'))}<section class="panel"><div class="toolbar"><input class="search" id="offerings-search" placeholder="Pesquisar tipo ou referência…" aria-label="Pesquisar ofertas"><span class="muted">${offerings.length} registo(s)</span></div><div id="offerings-table"></div></section>`; const render = () => { const term = ($('offerings-search').value || '').toLowerCase(); const rows = offerings.filter(x => `${x.offering_type} ${x.reference || ''} ${x.notes || ''}`.toLowerCase().includes(term)); $('offerings-table').innerHTML = rows.length ? `<div class="table-wrap"><table class="data-table"><thead><tr><th>Data</th><th>Tipo</th><th>Referência</th><th>Valor</th><th></th></tr></thead><tbody>${rows.map(x => `<tr><td>${dateText(x.business_date)}</td><td><span class="tag">${esc(x.offering_type)}</span></td><td>${esc(x.reference || '—')}</td><td class="amount">${money(x.amount_cents)}</td><td>${canWrite() ? `<div class="row-actions"><button class="action-link" data-edit-entry="offering" data-id="${x.id}">Editar</button><button class="action-link" data-delete-entry="offering" data-id="${x.id}">Apagar</button></div>` : ''}</td></tr>`).join('')}</tbody></table></div>` : '<div class="empty-state"><strong>Nenhuma oferta encontrada</strong><span>Comece por registar uma oferta.</span></div>'; }; render(); $('offerings-search').addEventListener('input', render); }
async function renderTithes() { await fetchFinancial('2000-01-01', '2999-12-31'); await fetchBrothers(); const tithes = state.tithes; $('page-content').innerHTML = `${pageHeading('Dízimos', 'Registos de dízimos por data de entrega e referência.', entryButton('tithe'))}<section class="panel"><div class="toolbar"><input class="search" id="tithes-search" placeholder="Pesquisar irmão ou referência…" aria-label="Pesquisar dízimos"><span class="muted">${tithes.length} registo(s)</span></div><div id="tithes-table"></div></section>`; const render = () => { const term = ($('tithes-search').value || '').toLowerCase(); const rows = tithes.filter(x => `${x.brother_name || ''} ${x.reference || ''} ${x.notes || ''}`.toLowerCase().includes(term)); $('tithes-table').innerHTML = rows.length ? `<div class="table-wrap"><table class="data-table"><thead><tr><th>Entrega</th><th>Irmão</th><th>Referência</th><th>Valor</th><th></th></tr></thead><tbody>${rows.map(x => `<tr><td>${dateText(x.delivery_date)}</td><td>${esc(x.brother_name || '—')}</td><td>${esc(x.reference || '—')}</td><td class="amount">${money(x.amount_cents)}</td><td>${canWrite() ? `<div class="row-actions"><button class="action-link" data-edit-entry="tithe" data-id="${x.id}">Editar</button><button class="action-link" data-delete-entry="tithe" data-id="${x.id}">Apagar</button></div>` : ''}</td></tr>`).join('')}</tbody></table></div>` : '<div class="empty-state"><strong>Nenhum dízimo encontrado</strong><span>Comece por registar um dízimo.</span></div>'; }; render(); $('tithes-search').addEventListener('input', render); }
async function renderBrothers() { const brothers = await fetchBrothers(); $('page-content').innerHTML = `${pageHeading('Irmãos', 'Cadastro opcional para facilitar os lançamentos de dízimos.', canWrite() ? '<button class="button primary" data-new-brother>+ Novo irmão</button>' : '')}<section class="panel"><div class="toolbar"><input class="search" id="brothers-search" placeholder="Pesquisar por nome ou telefone…" aria-label="Pesquisar irmãos"><span class="muted">${brothers.length} pessoa(s)</span></div><div id="brothers-table"></div></section>`; const render = () => { const term = ($('brothers-search').value || '').toLowerCase(); const rows = brothers.filter(x => `${x.full_name} ${x.phone || ''}`.toLowerCase().includes(term)); $('brothers-table').innerHTML = rows.length ? `<div class="table-wrap"><table class="data-table"><thead><tr><th>Nome completo</th><th>Telefone</th><th>Estado</th><th></th></tr></thead><tbody>${rows.map(x => `<tr><td><strong>${esc(x.full_name)}</strong></td><td>${esc(x.phone || '—')}</td><td><span class="tag ${x.active ? '' : 'gold'}">${x.active ? 'Ativo' : 'Inativo'}</span></td><td>${canWrite() ? `<div class="row-actions"><button class="action-link" data-edit-brother="${x.id}">Editar</button><button class="action-link" data-delete-brother="${x.id}">Apagar</button></div>` : ''}</td></tr>`).join('')}</tbody></table></div>` : '<div class="empty-state"><strong>Nenhum irmão encontrado</strong><span>Adicione um cadastro opcional.</span></div>'; }; render(); $('brothers-search').addEventListener('input', render); }
async function renderDay() { const date = state.selectedDate || $('day-date')?.value || today(); await fetchFinancial(date, date); const offers = state.offerings.filter(x => x.business_date === date); const tithes = state.tithes.filter(x => x.delivery_date === date); $('page-content').innerHTML = `${pageHeading('Registos por dia', 'Consulte tudo o que foi lançado numa data específica.', `<input type="date" id="day-date" class="select-control" value="${date}" aria-label="Escolher data">`)}<section class="summary-grid"><article class="summary-card"><span class="summary-label">Ofertas</span><strong class="summary-value">${money(total(offers))}</strong><span class="summary-meta">${offers.length} registo(s)</span></article><article class="summary-card"><span class="summary-label">Dízimos</span><strong class="summary-value">${money(total(tithes))}</strong><span class="summary-meta">${tithes.length} registo(s)</span></article><article class="summary-card"><span class="summary-label">Total geral</span><strong class="summary-value">${money(total(offers) + total(tithes))}</strong><span class="summary-meta">${offers.length + tithes.length} lançamento(s)</span></article></section><section class="panel"><div class="panel-head"><h3>Movimentos de ${dateText(date)}</h3><span>${offers.length + tithes.length} registo(s)</span></div>${offers.length || tithes.length ? `<div class="table-wrap"><table class="data-table"><thead><tr><th>Tipo</th><th>Detalhe</th><th>Referência</th><th>Valor</th><th>Hora</th></tr></thead><tbody>${[...offers.map(x => ({ ...x, kind: 'Oferta', detail: x.offering_type, date: x.business_date })), ...tithes.map(x => ({ ...x, kind: 'Dízimo', detail: x.brother_name || 'Dízimo', date: x.delivery_date }))].sort((a, b) => b.created_at.localeCompare(a.created_at)).map(x => `<tr><td><span class="tag ${x.kind === 'Dízimo' ? 'gold' : ''}">${x.kind}</span></td><td>${esc(x.detail)}</td><td>${esc(x.reference || '—')}</td><td class="amount">${money(x.amount_cents)}</td><td>${dateTimeText(x.created_at)}</td></tr>`).join('')}</tbody></table></div>` : '<div class="empty-state"><strong>Sem movimentos nesta data</strong><span>Escolha outra data ou registe um novo lançamento.</span></div>'}</section>`; $('day-date').addEventListener('change', e => { state.selectedDate = e.target.value; renderDay(); }); }
async function renderCalendar() {
  const current = state.calendarMonth || new Date().toISOString().slice(0, 7); state.calendarMonth = current; const [year, month] = current.split('-').map(Number); const from = `${current}-01`; const last = new Date(year, month, 0).getDate(); const to = `${current}-${String(last).padStart(2, '0')}`; const { offerings, tithes } = await fetchFinancial(from, to); const byDay = {}; [...offerings.map(x => ({ ...x, kind: 'offering', day: x.business_date })), ...tithes.map(x => ({ ...x, kind: 'tithe', day: x.delivery_date }))].forEach(row => { byDay[row.day] ||= { offering: 0, tithe: 0, count: 0 }; byDay[row.day][row.kind] += Number(row.amount_cents); byDay[row.day].count++; }); const first = new Date(year, month - 1, 1); const offset = (first.getDay() + 6) % 7; const cells = []; for (let i = 0; i < offset; i++) cells.push('<div class="calendar-cell muted-cell"></div>'); for (let day = 1; day <= last; day++) { const key = `${current}-${String(day).padStart(2, '0')}`; const item = byDay[key]; cells.push(`<button class="calendar-cell ${item ? 'has-movement' : ''}" data-calendar-date="${key}" aria-label="${dateText(key)}${item ? `, total ${money((item.offering || 0) + (item.tithe || 0))}` : ''}"><strong>${day}</strong>${item ? `<span class="calendar-total">${money(item.offering + item.tithe)}</span><span class="calendar-count">${item.count} reg.</span>` : '<span class="calendar-count">—</span>'}</button>`); } while (cells.length % 7) cells.push('<div class="calendar-cell muted-cell"></div>'); $('page-content').innerHTML = `${pageHeading('Calendário financeiro', 'Dias com movimento ficam destacados. Selecione uma data para abrir os detalhes.', `<input type="month" id="calendar-month" class="select-control" value="${current}" aria-label="Escolher mês">`)}<section class="panel"><div class="calendar-week"><span>Seg</span><span>Ter</span><span>Qua</span><span>Qui</span><span>Sex</span><span>Sáb</span><span>Dom</span></div><div class="calendar-grid">${cells.join('')}</div><div class="legend"><span><i class="green"></i> Dia com movimento</span></div></section>`; $('calendar-month').addEventListener('change', e => { state.calendarMonth = e.target.value; renderCalendar(); }); document.querySelectorAll('[data-calendar-date]').forEach(btn => btn.addEventListener('click', () => { state.selectedDate = btn.dataset.calendarDate; setView('day'); })); }

async function renderClosures() {
  const date = state.closureDate || today(); const { data: closure } = await supabase.from('daily_closures').select('*').eq('organization_id', state.organization.id).eq('business_date', date).maybeSingle(); await fetchFinancial(date, date); const offers = state.offerings, tithes = state.tithes; const closed = closure?.status === 'closed'; $('page-content').innerHTML = `${pageHeading('Fecho diário', 'Confirme os totais do dia e bloqueie alterações comuns.', `<input type="date" id="closure-date" class="select-control" value="${date}" aria-label="Data do fecho">`)}<section class="summary-grid"><article class="summary-card"><span class="summary-label">Ofertas</span><strong class="summary-value">${money(total(offers))}</strong><span class="summary-meta">${offers.length} registo(s)</span></article><article class="summary-card"><span class="summary-label">Dízimos</span><strong class="summary-value">${money(total(tithes))}</strong><span class="summary-meta">${tithes.length} registo(s)</span></article><article class="summary-card"><span class="summary-label">Total conferido</span><strong class="summary-value">${money(total(offers) + total(tithes))}</strong><span class="summary-meta">${offers.length + tithes.length} lançamento(s)</span></article><article class="summary-card"><span class="summary-label">Estado</span><strong class="summary-value">${closed ? 'Fechado' : 'Aberto'}</strong><span class="summary-meta">${closure?.closed_at ? `Em ${dateTimeText(closure.closed_at)}` : 'Pronto para fechar'}</span></article></section><section class="panel"><div class="panel-head"><div><h3>Conferência de ${dateText(date)}</h3><span>O fecho guarda um retrato dos totais no momento da confirmação.</span></div>${canWrite() && !closed ? `<button class="button primary" id="close-day-button">Confirmar fecho</button>` : ''}${isAdmin() && closed ? `<button class="button secondary" id="reopen-day-button">Reabrir dia</button>` : ''}</div>${closed ? `<div class="form-message success">Este dia está fechado. Alterações financeiras comuns estão bloqueadas.</div>` : '<div class="form-message">O dia continua aberto para lançamentos autorizados.</div>'}<div class="table-wrap"><table class="data-table"><thead><tr><th>Tipo</th><th>Descrição</th><th>Valor</th><th>Referência</th></tr></thead><tbody>${[...offers.map(x => ({ ...x, kind: 'Oferta', detail: x.offering_type })), ...tithes.map(x => ({ ...x, kind: 'Dízimo', detail: x.brother_name }))].map(x => `<tr><td><span class="tag ${x.kind === 'Dízimo' ? 'gold' : ''}">${x.kind}</span></td><td>${esc(x.detail)}</td><td class="amount">${money(x.amount_cents)}</td><td>${esc(x.reference || '—')}</td></tr>`).join('') || '<tr><td colspan="4">Sem lançamentos neste dia.</td></tr>'}</tbody></table></div></section>`; $('closure-date').addEventListener('change', e => { state.closureDate = e.target.value; renderClosures(); }); $('close-day-button')?.addEventListener('click', closeDay); $('reopen-day-button')?.addEventListener('click', reopenDay); }
async function closeDay() { if (!confirm(`Fechar o dia ${dateText(state.closureDate || today())}? Confira os totais antes de continuar.`)) return; const { error } = await supabase.rpc('close_day', { p_org: state.organization.id, p_date: state.closureDate || today(), p_notes: null }); if (error) return toast(error.message.includes('already_closed') ? 'Este dia já está fechado.' : 'Não foi possível fechar o dia.', true); toast('Fecho diário realizado.'); renderClosures(); }
async function reopenDay() { const reason = prompt('Informe o motivo da reabertura:'); if (!reason?.trim()) return; const { error } = await supabase.rpc('reopen_day', { p_org: state.organization.id, p_date: state.closureDate || today(), p_reason: reason.trim() }); if (error) return toast('Não foi possível reabrir o dia.', true); toast('Dia reaberto e alteração auditada.'); renderClosures(); }

async function renderReports() { const from = state.reportFrom || dateRange('month').from, to = state.reportTo || dateRange('month').to; $('page-content').innerHTML = `${pageHeading('Relatórios', 'Escolha um período, confira a pré-visualização e gere um PDF.', '')}<section class="panel"><div class="form-grid"><div class="field"><label for="report-from">Data inicial</label><input id="report-from" type="date" value="${from}"></div><div class="field"><label for="report-to">Data final</label><input id="report-to" type="date" value="${to}"></div></div><div class="form-grid"><div class="field"><label for="report-type">Tipo de relatório</label><select id="report-type"><option value="financeiro">Financeiro geral</option><option value="ofertas">Ofertas</option><option value="dizimos">Dízimos</option></select></div><div class="field"><label for="report-details">Detalhes</label><select id="report-details"><option value="yes">Incluir nomes e referências</option><option value="no">Apenas totais</option></select></div></div><button class="button primary" id="preview-report">Atualizar pré-visualização</button></section><section class="panel" id="report-preview"><div class="empty-state"><strong>Pré-visualização</strong><span>Escolha o período para carregar os dados.</span></div></section>`; const preview = async () => { const start = $('report-from').value, end = $('report-to').value; if (!start || !end || start > end) return toast('Escolha um intervalo válido.', true); state.reportFrom = start; state.reportTo = end; const { offerings, tithes } = await fetchFinancial(start, end); const type = $('report-type').value; const rows = [...(type !== 'dizimos' ? offerings.map(x => ({ date: x.business_date, kind: 'Oferta', name: x.offering_type, reference: x.reference, amount_cents: x.amount_cents })) : []), ...(type !== 'ofertas' ? tithes.map(x => ({ date: x.delivery_date, kind: 'Dízimo', name: x.brother_name, reference: x.reference, amount_cents: x.amount_cents })) : [])].sort((a,b) => a.date.localeCompare(b.date)); $('report-preview').innerHTML = `<div class="panel-head"><div><h3>Pré-visualização</h3><span>${dateText(start)} a ${dateText(end)} · ${rows.length} registo(s)</span></div><button class="button primary" id="generate-pdf">Gerar PDF</button></div><div class="summary-grid"><article class="summary-card"><span class="summary-label">Ofertas</span><strong class="summary-value">${money(total(offerings))}</strong></article><article class="summary-card"><span class="summary-label">Dízimos</span><strong class="summary-value">${money(total(tithes))}</strong></article><article class="summary-card"><span class="summary-label">Total geral</span><strong class="summary-value">${money(total(offerings) + total(tithes))}</strong></article></div>${rows.length ? `<div class="table-wrap"><table class="data-table"><thead><tr><th>Data</th><th>Tipo</th><th>Nome/descrição</th><th>Referência</th><th>Valor</th></tr></thead><tbody>${rows.slice(0, 100).map(x => `<tr><td>${dateText(x.date)}</td><td>${x.kind}</td><td>${esc(x.name)}</td><td>${esc(x.reference || '—')}</td><td class="amount">${money(x.amount_cents)}</td></tr>`).join('')}</tbody></table></div>${rows.length > 100 ? '<p class="muted">A prévia mostra os primeiros 100 registros; o PDF incluirá todos.</p>' : ''}` : '<div class="empty-state"><strong>Sem movimentos</strong><span>Não existem dados no período escolhido.</span></div>'}`; $('generate-pdf')?.addEventListener('click', () => generatePdf(rows, start, end, $('report-type').value, $('report-details').value === 'yes', offerings, tithes)); }; $('preview-report').addEventListener('click', preview); await preview(); }
async function generatePdf(rows, start, end, type, details, offerings, tithes) { if (!window.jspdf?.jsPDF) return toast('O gerador de PDF ainda não carregou. Verifique a conexão e tente novamente.', true); const { jsPDF } = window.jspdf; const doc = new jsPDF({ unit: 'mm', format: 'a4' }); const title = type === 'ofertas' ? 'Relatório de ofertas' : type === 'dizimos' ? 'Relatório de dízimos' : 'Relatório financeiro'; doc.setFillColor(18,53,47); doc.rect(0,0,210,28,'F'); doc.setTextColor(255,255,255); doc.setFontSize(15); doc.text(state.organization.name, 14, 12); doc.setFontSize(9); doc.text(`Sector ${state.organization.sector} · ${title}`, 14, 20); doc.setTextColor(23,42,39); doc.setFontSize(11); doc.text(`Período: ${dateText(start)} a ${dateText(end)}`, 14, 39); doc.setFontSize(10); doc.text(`Emitido em: ${dateTimeText(new Date().toISOString())}`, 14, 46); doc.text(`Ofertas: ${money(total(offerings))}`, 14, 56); doc.text(`Dízimos: ${money(total(tithes))}`, 80, 56); doc.text(`Total: ${money(total(offerings)+total(tithes))}`, 145, 56); const body = rows.map(x => details ? [dateText(x.date), x.kind, x.name, x.reference || '—', money(x.amount_cents)] : [dateText(x.date), x.kind, money(x.amount_cents)]); const head = details ? [['Data','Tipo','Nome/descrição','Referência','Valor']] : [['Data','Tipo','Valor']]; doc.autoTable({ startY: 64, head, body, theme: 'grid', headStyles: { fillColor: [18,53,47] }, styles: { fontSize: 8, cellPadding: 2.2 }, margin: { left: 14, right: 14 }, didDrawPage: () => { doc.setFontSize(8); doc.setTextColor(100); doc.text(`${state.organization.name} · Documento financeiro`, 14, 289); doc.text(`Página ${doc.internal.getNumberOfPages()}`, 180, 289); } }); doc.setFontSize(9); doc.setTextColor(80); doc.text('Assinatura: ____________________________________________', 14, Math.min(doc.lastAutoTable.finalY + 20, 275)); doc.save(`relatorio-${start}-${end}.pdf`); const { error } = await supabase.from('reports').insert({ organization_id: state.organization.id, report_type: type, filters: { start, end, details }, period_start: start, period_end: end, offerings_total_cents: total(offerings), tithes_total_cents: total(tithes), total_cents: total(offerings)+total(tithes), records_count: rows.length, generated_by: state.user.id }); if (error) console.warn('Relatório gerado, mas histórico não foi guardado.', error); else toast('PDF gerado e histórico guardado.'); }

async function renderAdmin() { const { data: members, error } = await supabase.from('organization_members').select('id,user_id,role,active,created_at,profiles(full_name,email)').eq('organization_id', state.organization.id).order('created_at'); if (error) throw error; $('page-content').innerHTML = `${pageHeading('Administração', 'Utilizadores, permissões e dados institucionais.', '')}<section class="panel"><div class="panel-head"><div><h3>Utilizadores</h3><span>Contas existentes podem ser associadas por e-mail.</span></div></div><div class="form-grid"><div class="field"><label for="member-email">E-mail do usuário já registado</label><input id="member-email" type="email" placeholder="E-mail da conta"></div><div class="field"><label for="member-role">Perfil</label><select id="member-role"><option value="viewer">Consulta</option><option value="treasurer">Tesoureiro</option><option value="admin">Administrador</option></select></div></div><button class="button primary" id="add-member">Adicionar usuário</button><div class="table-wrap" style="margin-top:1.2rem"><table class="data-table"><thead><tr><th>Nome</th><th>E-mail</th><th>Perfil</th><th>Estado</th><th>Ação</th></tr></thead><tbody>${members.map(m => `<tr><td>${esc(m.profiles?.full_name || '—')}</td><td>${esc(m.profiles?.email || '—')}</td><td><select class="member-role-select" data-member-id="${m.id}"><option value="viewer" ${m.role==='viewer'?'selected':''}>Consulta</option><option value="treasurer" ${m.role==='treasurer'?'selected':''}>Tesoureiro</option><option value="admin" ${m.role==='admin'?'selected':''}>Administrador</option></select></td><td>${m.active ? 'Ativo' : 'Bloqueado'}</td><td><button class="action-link" data-toggle-member="${m.id}" data-active="${m.active}">${m.active ? 'Bloquear' : 'Ativar'}</button></td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-head"><div><h3>Dados da igreja</h3><span>Estas informações aparecem nos relatórios.</span></div></div><div class="form-grid"><div class="field"><label for="settings-name">Nome da igreja</label><input id="settings-name" value="${esc(state.organization.name)}"></div><div class="field"><label for="settings-sector">Sector</label><input id="settings-sector" value="${esc(state.organization.sector)}"></div><div class="field"><label for="settings-contact">Contacto</label><input id="settings-contact" value="${esc(state.organization.contact || '')}"></div><div class="field"><label for="settings-responsible">Responsável</label><input id="settings-responsible" value="${esc(state.organization.responsible_name || '')}"></div></div><div class="field"><label for="settings-address">Endereço</label><input id="settings-address" value="${esc(state.organization.address || '')}"></div><div class="field"><label for="settings-logo">Logotipo <span class="optional">PNG/JPG, opcional</span></label><input id="settings-logo" type="file" accept="image/png,image/jpeg,image/webp"></div><button class="button primary" id="save-settings">Guardar configurações</button></section><section class="panel"><div class="panel-head"><div><h3>Backup e restauração</h3><span>Exportação protegida da organização em JSON. A restauração faz merge e não apaga dados automaticamente.</span></div></div><button class="button secondary" id="export-backup">Exportar backup</button><label class="button secondary" for="import-backup" style="margin-left:.4rem">Importar backup</label><input id="import-backup" type="file" accept="application/json" hidden></section>`; $('add-member').addEventListener('click', addMember); $('save-settings').addEventListener('click', saveSettings); $('export-backup').addEventListener('click', exportBackup); $('import-backup').addEventListener('change', importBackup); document.querySelectorAll('[data-toggle-member]').forEach(btn => btn.addEventListener('click', () => toggleMember(btn.dataset.toggleMember, btn.dataset.active === 'true'))); document.querySelectorAll('.member-role-select').forEach(sel => sel.addEventListener('change', () => changeMemberRole(sel.dataset.memberId, sel.value))); }
async function addMember() { const email = $('member-email').value.trim(), role = $('member-role').value; if (!email) return toast('Informe o e-mail da conta.', true); const { error } = await supabase.rpc('admin_add_member', { p_org: state.organization.id, p_email: email, p_role: role }); if (error) return toast(error.message.includes('not_found') ? 'Não existe uma conta com esse e-mail.' : 'Não foi possível adicionar o usuário.', true); toast('Usuário associado à igreja.'); renderAdmin(); }
async function changeMemberRole(id, role) { const { error } = await supabase.from('organization_members').update({ role }).eq('id', id).eq('organization_id', state.organization.id); if (error) return toast('Não foi possível alterar o perfil.', true); toast('Perfil atualizado.'); }
async function toggleMember(id, active) { if (!confirm(`${active ? 'Bloquear' : 'Ativar'} este usuário?`)) return; const { error } = await supabase.from('organization_members').update({ active: !active }).eq('id', id).eq('organization_id', state.organization.id); if (error) return toast('Não foi possível atualizar o usuário.', true); toast(active ? 'Usuário bloqueado.' : 'Usuário ativado.'); renderAdmin(); }
async function saveSettings() { const patch = { name: $('settings-name').value.trim(), sector: $('settings-sector').value.trim(), contact: $('settings-contact').value.trim() || null, responsible_name: $('settings-responsible').value.trim() || null, address: $('settings-address').value.trim() || null }; const file = $('settings-logo').files?.[0]; if (file) { if (file.size > 250 * 1024) return toast('No plano gratuito, o logotipo deve ter no máximo 250 KB.', true); patch.logo_data = await new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(reader.result); reader.onerror = reject; reader.readAsDataURL(file); }); } const { data, error } = await supabase.from('organizations').update(patch).eq('id', state.organization.id).select().single(); if (error) return toast('Não foi possível guardar as configurações.', true); state.organization = data; toast('Configurações guardadas.'); }
async function exportBackup() { const [offerings, tithes, brothers, closures] = await Promise.all([queryRows('offerings'), queryRows('tithes'), queryRows('brothers'), supabase.from('daily_closures').select('*').eq('organization_id', state.organization.id).then(r => r.data || [])]); const payload = { version: 1, exported_at: new Date().toISOString(), organization: state.organization, offerings, tithes, brothers, closures }; const content = JSON.stringify(payload, null, 2); const blob = new Blob([content], { type: 'application/json' }); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = `backup-alfa-omega-${today()}.json`; link.click(); URL.revokeObjectURL(link.href); toast('Backup exportado para este dispositivo.'); }
async function importBackup(event) { const file = event.target.files?.[0]; if (!file) return; if (!confirm('A restauração fará merge dos dados do arquivo. Deseja continuar?')) return; try { const payload = JSON.parse(await file.text()); if (payload.organization?.id !== state.organization.id) throw new Error('organization'); const { error } = await supabase.rpc('restore_organization', { p_org: state.organization.id, p_payload: payload }); if (error) throw error; toast('Backup restaurado com sucesso.'); await renderAdmin(); } catch { toast('Backup inválido ou incompatível com esta igreja.', true); } event.target.value = ''; }

function offerFields(row = {}) { return `<div class="form-grid"><div class="field"><label for="entry-date">Data</label><input id="entry-date" type="date" required value="${row.business_date || today()}"></div><div class="field"><label for="entry-amount">Valor (${esc(state.organization?.currency || 'MZN')})</label><input id="entry-amount" type="number" min="0.01" step="0.01" required value="${row.amount_cents ? (Number(row.amount_cents) / 100).toFixed(2) : ''}"></div></div><div class="field"><label for="entry-offering-type">Tipo de oferta</label><select id="entry-offering-type" required>${['Oferta do culto', 'Coleta', 'Oferta especial', 'Oferta missionária', 'Campanha', 'Oferta de gratidão', 'Construção', 'Outra'].map(x => `<option ${row.offering_type === x ? 'selected' : ''}>${x}</option>`).join('')}</select></div><div class="field"><label for="entry-reference">Referência <span class="optional">opcional</span></label><input id="entry-reference" value="${esc(row.reference || '')}" placeholder="Ex.: Culto de domingo"></div><div class="field"><label for="entry-notes">Observações <span class="optional">opcional</span></label><textarea id="entry-notes" rows="3">${esc(row.notes || '')}</textarea></div>`; }
function titheFields(row = {}) { const options = `<option value="">Inserir nome manualmente</option>${state.brothers.map(x => `<option value="${x.id}" ${row.brother_id === x.id ? 'selected' : ''}>${esc(x.full_name)}</option>`).join('')}`; return `<div class="form-grid"><div class="field"><label for="entry-date">Data de entrega</label><input id="entry-date" type="date" required value="${row.delivery_date || today()}"></div><div class="field"><label for="entry-amount">Valor (${esc(state.organization?.currency || 'MZN')})</label><input id="entry-amount" type="number" min="0.01" step="0.01" required value="${row.amount_cents ? (Number(row.amount_cents) / 100).toFixed(2) : ''}"></div></div><div class="field"><label for="entry-brother">Irmão cadastrado <span class="optional">opcional</span></label><select id="entry-brother">${options}</select></div><div class="field"><label for="entry-brother-name">Nome do irmão</label><input id="entry-brother-name" required value="${esc(row.brother_name || '')}" placeholder="Nome completo"></div><div class="field"><label for="entry-reference">Referência do dízimo</label><input id="entry-reference" required value="${esc(row.reference || '')}" placeholder="Ex.: Agosto de 2026"></div><div class="field"><label for="entry-notes">Observações <span class="optional">opcional</span></label><textarea id="entry-notes" rows="3">${esc(row.notes || '')}</textarea></div>`; }
async function openEntry(type, id = null) { if (type === 'tithe') await fetchBrothers(); const collection = type === 'offering' ? state.offerings : state.tithes; const row = id ? collection.find(x => x.id === id) : {}; $('entry-id').value = id || ''; $('entry-type').value = type; $('entry-title').textContent = id ? `Editar ${type === 'offering' ? 'oferta' : 'dízimo'}` : `Registar ${type === 'offering' ? 'oferta' : 'dízimo'}`; $('entry-fields').innerHTML = type === 'offering' ? offerFields(row) : titheFields(row); $('entry-message').hidden = true; openDialog('entry-dialog'); if (type === 'tithe') $('entry-brother')?.addEventListener('change', e => { const brother = state.brothers.find(x => x.id === e.target.value); if (brother) $('entry-brother-name').value = brother.full_name; }); }
async function saveEntry(event) { event.preventDefault(); const type = $('entry-type').value; const id = $('entry-id').value; const amount = Number($('entry-amount').value); if (!Number.isFinite(amount) || amount <= 0) return formMessage('entry-message', 'Informe um valor superior a zero.', true); const payload = { organization_id: state.organization.id, amount_cents: Math.round(amount * 100), reference: $('entry-reference').value.trim(), notes: $('entry-notes').value.trim(), updated_by: state.user.id }; if (type === 'offering') Object.assign(payload, { business_date: $('entry-date').value, offering_type: $('entry-offering-type').value }); else Object.assign(payload, { delivery_date: $('entry-date').value, brother_id: $('entry-brother').value || null, brother_name: $('entry-brother-name').value.trim() }); const button = $('entry-form').querySelector('button[type="submit"]'); setBusy(button, true); const table = type === 'offering' ? 'offerings' : 'tithes'; let result; if (id) result = await supabase.from(table).update(payload).eq('id', id).eq('organization_id', state.organization.id); else result = await supabase.from(table).insert({ ...payload, created_by: state.user.id, operation_id: crypto.randomUUID() }); setBusy(button, false); if (result.error) return formMessage('entry-message', result.error.message.includes('closed') ? 'Este dia está fechado e não pode ser alterado sem autorização.' : 'Não foi possível guardar o lançamento. Verifique os campos e tente novamente.', true); closeDialog('entry-dialog'); toast(id ? 'Lançamento atualizado.' : 'Lançamento registado.'); await renderView(); }
async function deleteEntry(type, id) { if (!confirm('Tem a certeza de que deseja apagar este lançamento? O histórico de auditoria será preservado.')) return; const table = type === 'offering' ? 'offerings' : 'tithes'; const { error } = await supabase.from(table).update({ deleted_at: new Date().toISOString(), deleted_by: state.user.id }).eq('id', id).eq('organization_id', state.organization.id); if (error) return toast('Não foi possível apagar o lançamento.', true); toast('Lançamento apagado.'); await renderView(); }
function openBrother(id = null) { const row = id ? state.brothers.find(x => x.id === id) : {}; $('brother-id').value = id || ''; $('brother-title').textContent = id ? 'Editar irmão' : 'Novo irmão'; $('brother-name').value = row.full_name || ''; $('brother-phone').value = row.phone || ''; $('brother-notes').value = row.notes || ''; formMessage('brother-message', ''); openDialog('brother-dialog'); }
async function saveBrother(event) { event.preventDefault(); const id = $('brother-id').value; const payload = { organization_id: state.organization.id, full_name: $('brother-name').value.trim(), phone: $('brother-phone').value.trim() || null, notes: $('brother-notes').value.trim() || null, updated_by: state.user.id }; if (!payload.full_name) return formMessage('brother-message', 'Informe o nome completo.', true); const button = $('brother-form').querySelector('button[type="submit"]'); setBusy(button, true); const result = id ? await supabase.from('brothers').update(payload).eq('id', id).eq('organization_id', state.organization.id) : await supabase.from('brothers').insert({ ...payload, created_by: state.user.id, operation_id: crypto.randomUUID() }); setBusy(button, false); if (result.error) return formMessage('brother-message', 'Não foi possível guardar o cadastro.', true); closeDialog('brother-dialog'); toast(id ? 'Cadastro atualizado.' : 'Irmão adicionado.'); await renderBrothers(); }
async function deleteBrother(id) { if (!confirm('Apagar este cadastro? Os dízimos já registados não serão apagados.')) return; const { error } = await supabase.from('brothers').update({ deleted_at: new Date().toISOString(), deleted_by: state.user.id }).eq('id', id).eq('organization_id', state.organization.id); if (error) return toast('Não foi possível apagar o cadastro.', true); toast('Cadastro apagado.'); await renderBrothers(); }
async function createOrganization(event) { event.preventDefault(); const button = $('setup-form').querySelector('button[type="submit"]'); setBusy(button, true, 'A configurar…'); const { data, error } = await supabase.rpc('create_organization', { p_name: $('setup-name').value.trim(), p_sector: $('setup-sector').value.trim(), p_currency: $('setup-currency').value, p_address: $('setup-address').value.trim() || null }); setBusy(button, false); if (error) return formMessage('setup-message', 'Não foi possível concluir a configuração. Tente novamente.', true); closeDialog('setup-dialog'); toast('Igreja configurada com segurança.'); await loadWorkspace(); }
async function handleLogin(event) { event.preventDefault(); if (!supabase) return; const button = event.submitter; setBusy(button, true, 'A entrar…'); const { error } = await supabase.auth.signInWithPassword({ email: $('login-email').value.trim(), password: $('login-password').value }); setBusy(button, false); if (error) return showAuthMessage('E-mail ou palavra-passe inválidos.'); showAuthMessage(''); }
async function handleRegister(event) { event.preventDefault(); if (!supabase) return; if ($('register-password').value !== $('register-confirm').value) return showAuthMessage('As palavras-passe não coincidem.'); const button = event.submitter; setBusy(button, true, 'A criar…'); const { data, error } = await supabase.auth.signUp({ email: $('register-email').value.trim(), password: $('register-password').value, options: { data: { full_name: $('register-name').value.trim() } } }); setBusy(button, false); if (error) return showAuthMessage(error.message.includes('already') ? 'Este e-mail já está registado.' : 'Não foi possível criar a conta. Verifique os dados.'); if (!data.session) showAuthMessage('Conta criada. Verifique o seu e-mail antes de entrar.', false); else showAuthMessage('Conta criada. Complete a configuração inicial.', false); }
async function forgotPassword() { if (!supabase) return; const email = $('login-email').value.trim(); if (!email) return showAuthMessage('Informe primeiro o seu e-mail.'); const { error } = await supabase.auth.resetPasswordForEmail(email, { redirectTo: window.location.href }); if (error) return showAuthMessage('Não foi possível enviar o e-mail de recuperação.'); showAuthMessage('Enviámos um link de recuperação para o seu e-mail.', false); }
function bindEvents() {
  document.querySelectorAll('[data-auth-mode]').forEach(btn => btn.addEventListener('click', () => setAuthMode(btn.dataset.authMode)));
  $('login-form').addEventListener('submit', handleLogin); $('register-form').addEventListener('submit', handleRegister); $('forgot-password').addEventListener('click', forgotPassword); $('setup-form').addEventListener('submit', createOrganization); $('entry-form').addEventListener('submit', saveEntry); $('brother-form').addEventListener('submit', saveBrother);
  $('logout-button').addEventListener('click', async () => { await supabase.auth.signOut(); window.location.reload(); }); $('theme-toggle').addEventListener('click', () => { document.body.classList.toggle('dark'); localStorage.setItem('ao-theme', document.body.classList.contains('dark') ? 'dark' : 'light'); }); if (localStorage.getItem('ao-theme') === 'dark') document.body.classList.add('dark');
  document.querySelectorAll('[data-close-dialog]').forEach(btn => btn.addEventListener('click', () => closeDialog(btn.dataset.closeDialog))); document.querySelectorAll('[data-view]').forEach(btn => btn.addEventListener('click', () => setView(btn.dataset.view))); $('open-sidebar').addEventListener('click', () => { $('sidebar').classList.add('open'); $('mobile-overlay').hidden = false; }); $('close-sidebar').addEventListener('click', () => { $('sidebar').classList.remove('open'); $('mobile-overlay').hidden = true; }); $('mobile-overlay').addEventListener('click', () => { $('sidebar').classList.remove('open'); $('mobile-overlay').hidden = true; });
  $('page-content').addEventListener('click', async (event) => { const newEntry = event.target.closest('[data-new-entry]'); if (newEntry) return openEntry(newEntry.dataset.newEntry); const edit = event.target.closest('[data-edit-entry]'); if (edit) return openEntry(edit.dataset.editEntry, edit.dataset.id); const del = event.target.closest('[data-delete-entry]'); if (del) return deleteEntry(del.dataset.deleteEntry, del.dataset.id); const newBrother = event.target.closest('[data-new-brother]'); if (newBrother) return openBrother(); const editBrother = event.target.closest('[data-edit-brother]'); if (editBrother) return openBrother(editBrother.dataset.editBrother); const delBrother = event.target.closest('[data-delete-brother]'); if (delBrother) return deleteBrother(delBrother.dataset.deleteBrother); const view = event.target.closest('[data-view]'); if (view) return setView(view.dataset.view); });
}
async function boot() {
  bindEvents();
  if (!configured) { showAuthMessage('Configure o ficheiro config.js com o URL e a chave pública do Supabase para iniciar.'); $('login-form').querySelectorAll('input,button').forEach(x => x.disabled = true); $('register-form').querySelectorAll('input,button').forEach(x => x.disabled = true); return; }
  const { data: { session } } = await supabase.auth.getSession(); if (session) { state.user = session.user; try { await loadWorkspace(); } catch (error) { console.error(error); showAuthMessage('Não foi possível carregar o espaço de trabalho.'); } }
  supabase.auth.onAuthStateChange(async (_event, session) => { state.user = session?.user || null; if (state.user) { try { await loadWorkspace(); } catch (error) { console.error(error); } } else { $('app-view').hidden = true; $('auth-view').hidden = false; } });
}
boot();
